package com.muoniumplayer.configskija.host.migration;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;

/** Bounded data-only parser. No class loading, tags, constructors, aliases or object deserialization. */
public final class LegacyData {
    private LegacyData() {}
    public static Object parse(String fileName,String text) {
        if(text.length()>4_194_304)throw new IllegalArgumentException("Legacy document exceeds 4 MiB character limit");
        String clean=text.startsWith("\uFEFF")?text.substring(1):text;
        if(fileName.endsWith(".json"))return new Json(clean).parse();
        if(fileName.endsWith(".yml")||fileName.endsWith(".yaml"))return yaml(clean);
        if(fileName.endsWith(".toml"))return toml(clean);
        throw new IllegalArgumentException("Unsupported legacy format");
    }
    @SuppressWarnings("unchecked") public static Map<String,Object> object(Object value) {
        if(!(value instanceof Map<?,?> map))throw new IllegalArgumentException("Expected data object");
        for(Object key:map.keySet())if(!(key instanceof String))throw new IllegalArgumentException("Expected string property key");
        return (Map<String,Object>)map;
    }
    private static void put(Map<String,Object> map,String key,Object value){if(map.containsKey(key))throw new IllegalArgumentException("Duplicate data key");map.put(key,value);}
    private static final class Json {
        final String text;int at,nodes;Json(String text){this.text=text;}
        Object parse(){Object value=value(0);space();if(at!=text.length())throw new IllegalArgumentException("Trailing JSON data");return value;}
        void space(){while(at<text.length()&&" \t\r\n".indexOf(text.charAt(at))>=0)at++;}
        Object value(int depth){space();if(depth>40||++nodes>100_000)throw new IllegalArgumentException("Legacy nesting/item limit");if(at>=text.length())throw new IllegalArgumentException("Truncated JSON");char c=text.charAt(at);
            if(c=='{'){at++;Map<String,Object> out=new LinkedHashMap<>();space();if(take('}'))return out;do{space();String key=string();space();expect(':');put(out,key,value(depth+1));space();if(take('}'))return out;expect(',');}while(true);}
            if(c=='['){at++;List<Object> out=new ArrayList<>();space();if(take(']'))return out;do{out.add(value(depth+1));space();if(take(']'))return out;expect(',');}while(true);}
            if(c=='"')return string();for(String literal:List.of("true","false","null"))if(text.startsWith(literal,at)){at+=literal.length();return literal.equals("null")?null:Boolean.valueOf(literal);}
            int start=at;while(at<text.length()&&"-+0123456789.eE".indexOf(text.charAt(at))>=0)at++;if(start==at)throw new IllegalArgumentException("Invalid JSON value");return number(text.substring(start,at));}
        String string(){expect('"');StringBuilder out=new StringBuilder();while(at<text.length()){char c=text.charAt(at++);if(c=='"')return out.toString();if(c<32)throw new IllegalArgumentException("Control character in string");if(c!='\\'){out.append(c);continue;}if(at>=text.length())throw new IllegalArgumentException("Truncated escape");char escaped=text.charAt(at++);switch(escaped){case '"','\\','/'->out.append(escaped);case 'b'->out.append('\b');case 'f'->out.append('\f');case 'n'->out.append('\n');case 'r'->out.append('\r');case 't'->out.append('\t');case 'u'->{if(at+4>text.length())throw new IllegalArgumentException("Truncated unicode escape");try{out.append((char)Integer.parseInt(text.substring(at,at+4),16));}catch(NumberFormatException e){throw new IllegalArgumentException("Invalid unicode escape");}at+=4;}default->throw new IllegalArgumentException("Unknown escape");}}throw new IllegalArgumentException("Unterminated string");}
        boolean take(char c){if(at<text.length()&&text.charAt(at)==c){at++;return true;}return false;}void expect(char c){if(!take(c))throw new IllegalArgumentException("Expected JSON delimiter at offset "+at);}
    }
    private static Number number(String text){if(!text.matches("-?(?:0|[1-9][0-9]*)(?:\\.[0-9]+)?(?:[eE][+-]?[0-9]+)?"))throw new IllegalArgumentException("Invalid numeric literal");try{if(!text.contains(".")&&!text.contains("e")&&!text.contains("E"))return Long.valueOf(text);double value=Double.parseDouble(text);if(!Double.isFinite(value))throw new IllegalArgumentException("Nonfinite numeric literal");return value;}catch(NumberFormatException error){throw new IllegalArgumentException("Numeric literal out of range");}}
    private record Line(int indent,String text){}
    private static Object yaml(String text){List<Line> lines=new ArrayList<>();for(String raw:text.split("\\r?\\n")){if(raw.indexOf('\t')>=0)throw new IllegalArgumentException("Tabs in YAML indentation");String stripped=uncomment(raw).stripTrailing();if(stripped.isBlank()||stripped.trim().equals("---")||stripped.trim().equals("..."))continue;int indent=0;while(indent<stripped.length()&&stripped.charAt(indent)==' ')indent++;String data=stripped.substring(indent);if(data.startsWith("!")||data.startsWith("&")||data.startsWith("*")||data.startsWith("%"))throw new IllegalArgumentException("Unsupported YAML tag/alias/directive");lines.add(new Line(indent,data));if(lines.size()>100_000)throw new IllegalArgumentException("YAML item limit");}if(lines.isEmpty())return new LinkedHashMap<>();Cursor cursor=new Cursor();Object out=yamlBlock(lines,cursor,lines.get(0).indent,0);if(cursor.at!=lines.size())throw new IllegalArgumentException("Unexpected YAML indentation");return out;}
    private static final class Cursor{int at;}
    private static Object yamlBlock(List<Line> lines,Cursor cursor,int indent,int depth){if(depth>40)throw new IllegalArgumentException("YAML depth limit");boolean array=lines.get(cursor.at).text.startsWith("- ")||lines.get(cursor.at).text.equals("-");List<Object> list=new ArrayList<>();Map<String,Object> map=new LinkedHashMap<>();while(cursor.at<lines.size()&&lines.get(cursor.at).indent==indent){Line line=lines.get(cursor.at);String part=line.text;if(array&&!part.startsWith("-"))break;cursor.at++;if(array){String value=part.substring(1).trim();if(value.isEmpty()){if(cursor.at<lines.size()&&lines.get(cursor.at).indent>indent)list.add(yamlBlock(lines,cursor,lines.get(cursor.at).indent,depth+1));else list.add(null);}else list.add(scalar(value));}else{int separator=outside(part,':');if(separator<=0)throw new IllegalArgumentException("Unsupported YAML mapping syntax");String key=key(part.substring(0,separator).trim()),value=part.substring(separator+1).trim();Object parsed;if(value.isEmpty()&&cursor.at<lines.size()&&(lines.get(cursor.at).indent>indent||lines.get(cursor.at).indent==indent&&lines.get(cursor.at).text.startsWith("- ")))parsed=yamlBlock(lines,cursor,lines.get(cursor.at).indent,depth+1);else parsed=value.isEmpty()?null:scalar(value);put(map,key,parsed);}}return array?list:map;}
    private static Map<String,Object> toml(String text){Map<String,Object> root=new LinkedHashMap<>(),section=root;int lines=0;for(String raw:text.split("\\r?\\n")){if(++lines>100_000)throw new IllegalArgumentException("TOML item limit");String line=uncomment(raw).trim();if(line.isEmpty())continue;if(line.startsWith("[["))throw new IllegalArgumentException("TOML array tables require explicit schema support");if(line.startsWith("[")&&line.endsWith("]")){section=root;for(String segment:line.substring(1,line.length()-1).split("\\.")){String key=key(segment.trim());Object child=section.get(key);if(child==null){child=new LinkedHashMap<String,Object>();section.put(key,child);}section=object(child);}continue;}int equal=outside(line,'=');if(equal<1)throw new IllegalArgumentException("Unsupported TOML line");String name=key(line.substring(0,equal).trim());if(name.contains("."))throw new IllegalArgumentException("Dotted TOML keys require explicit table");put(section,name,scalar(line.substring(equal+1).trim()));}return root;}
    private static String key(String value){if(value.startsWith("\"")||value.startsWith("'"))return Objects.toString(scalar(value));if(value.isEmpty()||value.equals("<<")||value.indexOf('\0')>=0)throw new IllegalArgumentException("Invalid property key");return value;}
    private static final ThreadLocal<Integer> SCALAR_DEPTH = ThreadLocal.withInitial(()->0);
    private static Object scalar(String value){int depth=SCALAR_DEPTH.get();if(depth>40)throw new IllegalArgumentException("Flow nesting limit");SCALAR_DEPTH.set(depth+1);try{return scalarValue(value);}finally{if(depth==0)SCALAR_DEPTH.remove();else SCALAR_DEPTH.set(depth);}}
    private static Object scalarValue(String value){if(value.startsWith("\"")&&value.endsWith("\""))return new Json(value).parse();if(value.startsWith("'")&&value.endsWith("'"))return value.substring(1,value.length()-1).replace("''","'");if(value.startsWith("[")&&value.endsWith("]")){List<Object> out=new ArrayList<>();for(String item:split(value.substring(1,value.length()-1),','))if(!item.isBlank())out.add(scalar(item.trim()));return out;}if(value.startsWith("{")&&value.endsWith("}")){Map<String,Object> out=new LinkedHashMap<>();for(String item:split(value.substring(1,value.length()-1),',')){if(item.isBlank())continue;int separator=outside(item,':');if(separator<0)separator=outside(item,'=');if(separator<1)throw new IllegalArgumentException("Unsupported flow object");put(out,key(item.substring(0,separator).trim()),scalar(item.substring(separator+1).trim()));}return out;}if(value.equals("true")||value.equals("false"))return Boolean.valueOf(value);if(value.equals("null")||value.equals("~"))return null;if(value.matches("-?[0-9].*"))return number(value);if(value.startsWith("|")||value.startsWith(">")||value.startsWith("!")||value.startsWith("&")||value.startsWith("*"))throw new IllegalArgumentException("Unsupported YAML literal/tag/alias");return value;}
    private static String uncomment(String raw){int at=outside(raw,'#');return at<0?raw:raw.substring(0,at);}
    private static int outside(String text,char target){char quote=0;boolean escape=false;int depth=0;for(int i=0;i<text.length();i++){char c=text.charAt(i);if(escape){escape=false;continue;}if(quote!=0){if(c=='\\'&&quote=='"')escape=true;else if(c==quote)quote=0;continue;}if(c=='"'||c=='\''){quote=c;continue;}if(c==target&&depth==0)return i;if(c=='['||c=='{')depth++;if(c==']'||c=='}')depth--;}return -1;}
    private static List<String> split(String text,char separator){List<String> out=new ArrayList<>();int start=0;while(start<text.length()){int next=outside(text.substring(start),separator);if(next<0){out.add(text.substring(start));return out;}out.add(text.substring(start,start+next));start+=next+1;}return out;}
}
